import{_ as a,o as r,c as e,a2 as i}from"./chunks/framework.iXqqCa-C.js";const l="/images/agent-chat.webp",o="/images/agent-search.webp",n="/images/agent-models.webp",s="/images/agent-sessions.webp",b=JSON.parse('{"title":"聊天与会话","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/chat.md","filePath":"guide/agent/chat.md","lastUpdated":1793501934000}'),d={name:"guide/agent/chat.md"};function g(h,t,p,u,c,m){return r(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="聊天与会话" tabindex="-1">聊天与会话 <a class="header-anchor" href="#聊天与会话" aria-label="Permalink to &quot;聊天与会话&quot;">​</a></h1><p>会话页顶部有以下标签页：</p><table tabindex="0"><thead><tr><th>标签页</th><th>作用</th></tr></thead><tbody><tr><td>消息</td><td>对话主界面</td></tr><tr><td>搜索</td><td>在当前会话中检索历史消息</td></tr><tr><td>模型</td><td>查看和切换本次对话使用的 AI 模型</td></tr><tr><td>生图</td><td>配置对话中自动插图</td></tr><tr><td>主动消息</td><td>让角色主动找你，详见<a href="/guide/agent/proactive">主动消息</a></td></tr><tr><td>记忆</td><td>让角色记住之前聊过的内容，详见<a href="/guide/agent/memory">记忆</a></td></tr><tr><td>世界书</td><td>查看角色的背景知识设定</td></tr><tr><td>规则</td><td>查看角色规则，开关可切换规则，详见<a href="/guide/agent/rules">规则</a></td></tr><tr><td>对话风格</td><td>切换当前会话的对话风格</td></tr><tr><td>会话</td><td>重命名、删除、导入导出等会话级设置</td></tr></tbody></table><h2 id="消息" tabindex="-1">消息 <a class="header-anchor" href="#消息" aria-label="Permalink to &quot;消息&quot;">​</a></h2><p><strong>发送消息</strong>：支持文字和图片。发送图片后角色会「看图」并回应（识图），图片菜单中的「传给 AI 的识图内容」显示模型实际看到的描述。不支持发送视频等其他文件。</p><p><strong>输出形态</strong>：</p><ul><li><strong>分段输出</strong>：较长的回复按段落拆成多个气泡逐段显示，在「会话」标签页开关。</li><li><strong>上下文边界</strong>：对话太长时，界面会出现一条分界线。线以上的消息<strong>不再原文发给模型</strong>，角色通过<a href="/guide/agent/memory">记忆</a>回顾这部分内容。</li><li>消息按日期自动分隔。角色触发世界书条目时，会提示本轮激活了哪些条目。</li></ul><p><strong>消息操作</strong>：每条消息都可以编辑、删除或「回溯」（对话回到这一条重新开始）。角色的回复可以重新生成，生成过程中可以随时中止。</p><p><strong>发送限制</strong>：角色回复完成前不能发送下一条消息。</p><p><strong>表情</strong>：输入框的表情按钮可以插入全站自定义表情（<code>:名字:</code>）。角色配置了专属表情包时，会在合适的时机发送贴纸。语法详见<a href="/guide/agent/syntax">对话语法</a>。</p><p><img src="'+l+'" alt="智能体消息"></p><h2 id="搜索" tabindex="-1">搜索 <a class="header-anchor" href="#搜索" aria-label="Permalink to &quot;搜索&quot;">​</a></h2><p>在当前会话内按关键词检索所有历史消息，点击结果直接定位并高亮那条消息。</p><p><img src="'+o+'" alt="智能体搜索"></p><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><p>为当前会话选择对话模型。每个模型以卡片展示：</p><ul><li><strong>上下文长度</strong>：一次能读进模型的内容量上限。</li><li><strong>输出上限</strong>：单次回复最多生成的量。</li><li><strong>费用</strong>：每次发送预计扣除的额度（卡片上会显示「预计单次发送费用」）。</li><li><strong>成功率（1 小时）</strong>：近期调用成功的比例，仅作参考。</li></ul><p>切换模型只影响当前会话。</p><ul><li>部分模型有<strong>每日免费次数</strong>，卡片上显示「今日免费」已用 / 总次数，次数内不扣额度，每天重置。</li><li>模型持续报错或回复异常时，可以点「上报异常」填写说明提交给管理员。</li><li>已选模型被下架或停用时，发送会提示并把内容退回输入框，重新选择模型即可。</li><li>模型有更新时，进入会话会弹出公告，点「我知道了」后不再提示。</li></ul><p><img src="'+n+'" alt="模型选择"></p><p>「智能体 → 模型」页列出全部对话模型和生图模型，也可以在这里上报异常和添加<a href="/guide/agent/usage#自定义模型">自定义模型</a>。</p><h2 id="生图" tabindex="-1">生图 <a class="header-anchor" href="#生图" aria-label="Permalink to &quot;生图&quot;">​</a></h2><p>「生图」标签页配置对话中的插图：</p><ul><li>选择生图模型（卡片展示每张费用和成功率），选「无」则关闭。</li><li>开启后，角色会根据对话内容在合适的时机生成插图。</li><li>角色设置了<strong>默认生图参考图</strong>时，支持参考图的模型会一并收到这些图，插图中的形象更稳定。</li><li>「自动生图张数」决定每轮自动生成几张，修改后自动保存；超出的图片指令需要手动点击生成。</li><li>生成的图片经过内容审核，不合规的会被拦截并提示原因。保存失败（网盘空间不足、文件类型不允许、额度不足）时也会提示原因。</li><li>生成的图片保存在网盘的「AI 智能体生成图片」文件夹。该文件夹单独计算空间，空间不足时自动清理最旧的图片，聊天中对应位置显示「图片已自动清理」。</li></ul><h2 id="会话" tabindex="-1">会话 <a class="header-anchor" href="#会话" aria-label="Permalink to &quot;会话&quot;">​</a></h2><p>「会话」标签页管理当前会话：</p><ul><li><strong>重命名 / 删除</strong>会话。删除<strong>不可恢复</strong>，会一并删除本会话的消息记录和便签，模型调用记录保留。</li><li><strong>导入 / 导出</strong>聊天记录备份（导入最多 10000 条）。</li><li><strong>分段输出</strong>开关。</li><li><strong>时间感知</strong>开关：把当前北京时间告诉角色，默认开启。<a href="/guide/agent/proactive">主动消息</a>依赖此开关。</li><li>长期闲置、没有对话内容（无消息或只有开场白）的会话会被系统定期清理。</li></ul><h2 id="回溯与多线" tabindex="-1">回溯与多线 <a class="header-anchor" href="#回溯与多线" aria-label="Permalink to &quot;回溯与多线&quot;">​</a></h2><ul><li>同一角色可以开多个会话，各会话的消息和记忆互相独立。</li><li>回溯会丢弃该消息之后的内容，适合尝试不同的剧情走向。</li></ul><p><img src="'+s+'" alt="智能体会话列表"></p><h2 id="对话中会遇到的状态" tabindex="-1">对话中会遇到的状态 <a class="header-anchor" href="#对话中会遇到的状态" aria-label="Permalink to &quot;对话中会遇到的状态&quot;">​</a></h2><ul><li><strong>会话被封禁</strong>：进入会话只显示处置页和封禁原因，仅保留「导出会话」和「删除会话」两个入口，无法查看消息记录。认为误判请<a href="/guide/faq#联系项目组">联系项目组</a>。</li><li><strong>角色被封禁</strong>：该角色下的会话无法继续发送消息或修改设置，但仍可查看历史记录。</li><li><strong>回复生成失败</strong>：提示中标注错误类型（超时、上游请求失败等），发送的内容会退回输入框，直接重试即可。失败的请求不计费。</li></ul>',32)])])}const f=a(d,[["render",g]]);export{b as __pageData,f as default};
